  sundial(g, { x: 29, z: 6 });
  urn(g, { x: 29, z: 25 });

  // 7. lamp posts: plaza corners, sundial and urn ends
  for (const [x, z] of [[27, 14], [27, 16], [31, 14], [31, 16], [28, 6], [30, 6], [28, 24], [30, 24]]) lamp(g, x, 1, z, 3);

